import{_ as d,o as a,c as e,a2 as o}from"./chunks/framework.C4u7U0Dw.js";const u=JSON.parse('{"title":"第 24 章 内置技能库（一）：图像与视频生成","description":"","frontmatter":{},"headers":[],"relativePath":"bluebook/第五篇 平台能力全景/第 24 章 内置技能库（一）：图像与视频生成.md","filePath":"bluebook/第五篇 平台能力全景/第 24 章 内置技能库（一）：图像与视频生成.md"}'),n={name:"bluebook/第五篇 平台能力全景/第 24 章 内置技能库（一）：图像与视频生成.md"};function s(r,t,l,i,p,h){return a(),e("div",null,[...t[0]||(t[0]=[o(`<h1 id="第-24-章-内置技能库-一-图像与视频生成" tabindex="-1">第 24 章 内置技能库（一）：图像与视频生成 <a class="header-anchor" href="#第-24-章-内置技能库-一-图像与视频生成" aria-label="Permalink to &quot;第 24 章 内置技能库（一）：图像与视频生成&quot;">​</a></h1><blockquote><p>本章目标：把 4 个图像技能和 7 个视频技能讲透——<strong>什么时候用哪个、提示词怎么给、为什么我总要先给你一份脚本</strong>。读完你应该能一句话说清：&quot;这个活儿该派谁。&quot;</p></blockquote><h2 id="_24-1-先说结论-能生成-但关键在-可控" tabindex="-1">24.1 先说结论：能生成，但关键在&quot;可控&quot; <a class="header-anchor" href="#_24-1-先说结论-能生成-但关键在-可控" aria-label="Permalink to &quot;24.1 先说结论：能生成，但关键在&quot;可控&quot;&quot;">​</a></h2><p>很多人第一次问我&quot;你能画图吗&quot;，得到肯定答复后，就随手丢一句：</p><blockquote><p>&quot;给我画个好看的海报。&quot;</p></blockquote><p>结果当然不理想。然后他会得出一个错误结论：<em>&quot;AI 画图不行。&quot;</em></p><p>真正的问题不在模型，在<strong>协作方式</strong>。图像和视频生成有一个和文本生成完全不同的特性：</p><table tabindex="0"><thead><tr><th>特性</th><th>写文档</th><th>生成图片 / 视频</th></tr></thead><tbody><tr><td>修改成本</td><td>极低，改字就行</td><td>高，要重新生成</td></tr><tr><td>单次耗时</td><td>几秒</td><td>几十秒到几分钟</td></tr><tr><td>结果确定性</td><td>高</td><td>低（同样提示词结果会变）</td></tr><tr><td>你需要的控制</td><td>内容</td><td><strong>风格、构图、光线、镜头</strong></td></tr></tbody></table><p>所以正确的做法不是&quot;丢一句话&quot;，而是<strong>把你知道的视觉意图提前说清楚</strong>。这一章剩下的内容，本质上都在讲怎么把这四件事说清楚。</p><h2 id="_24-2-图像生成-四个模型怎么选" tabindex="-1">24.2 图像生成：四个模型怎么选 <a class="header-anchor" href="#_24-2-图像生成-四个模型怎么选" aria-label="Permalink to &quot;24.2 图像生成：四个模型怎么选&quot;">​</a></h2><p>平台内置 4 个图像技能，它们不是&quot;重复的四个工具&quot;，而是<strong>四种不同的特长</strong>：</p><table tabindex="0"><thead><tr><th>技能</th><th>模型</th><th>最擅长</th><th>典型场景</th><th>提示词语言</th></tr></thead><tbody><tr><td><code>dalle3-image-gen</code></td><td>DALL·E 3</td><td>理解复杂描述、语义准确</td><td>概念图、插画、需要&quot;它真的听懂&quot;的画面</td><td><strong>英文优先</strong></td></tr><tr><td><code>flux-image-gen</code></td><td>FLUX</td><td><strong>文字渲染</strong>、复杂构图、写实</td><td>带文字的图、海报、高质量写实</td><td>中英皆可</td></tr><tr><td><code>midjourney-image-gen</code></td><td>Midjourney</td><td>艺术化、风格化、美学质感</td><td>概念设计、氛围图、创意视觉</td><td>中英皆可（参数制）</td></tr><tr><td><code>stable-diffusion-image-gen</code></td><td>Stable Diffusion</td><td>精细控制、图生图</td><td>写实照片、二次元、需要反复微调</td><td>正/负向提示词</td></tr></tbody></table><h3 id="_24-2-1-怎么选-三个判断问题" tabindex="-1">24.2.1 怎么选：三个判断问题 <a class="header-anchor" href="#_24-2-1-怎么选-三个判断问题" aria-label="Permalink to &quot;24.2.1 怎么选：三个判断问题&quot;">​</a></h3><ol><li><strong>画面里要不要出现字？</strong> → 要，优先 FLUX（它就是靠文字渲染吃饭的）；</li><li><strong>要&quot;像照片&quot;还是&quot;像作品&quot;？</strong> → 像照片选 FLUX / SD，像作品选 Midjourney；</li><li><strong>需要反复微调同一张图吗？</strong> → 需要就选 SD（正负向提示词 + 图生图最灵活）。</li></ol><p>如果你懒得判断，直接说用途即可，我会替你选：<em>&quot;做一张带标题的公众号封面图&quot;</em> 比 <em>&quot;用 flux 画图&quot;</em> 更有效。</p><h3 id="_24-2-2-dall·e-3-的关键参数" tabindex="-1">24.2.2 DALL·E 3 的关键参数 <a class="header-anchor" href="#_24-2-2-dall·e-3-的关键参数" aria-label="Permalink to &quot;24.2.2 DALL·E 3 的关键参数&quot;">​</a></h3><p>这是唯一一个把参数写死在技能里、可控性最强的图像技能：</p><table tabindex="0"><thead><tr><th>参数</th><th>可选值</th><th>默认</th></tr></thead><tbody><tr><td>尺寸</td><td><code>1024x1024</code>、<code>1792x1024</code>（横）、<code>1024x1792</code>（竖）</td><td><code>1024x1024</code></td></tr><tr><td>质量</td><td><code>standard</code>、<code>hd</code></td><td><code>standard</code></td></tr><tr><td>风格</td><td><code>vivid</code>（戏剧化）、<code>natural</code>（自然）</td><td><code>vivid</code></td></tr><tr><td>数量</td><td>1</td><td>1</td></tr></tbody></table><blockquote><p>尺寸选错是最常见的浪费：<strong>竖版图不要用方图裁</strong>，直接要 <code>1024x1792</code>。</p></blockquote><h2 id="_24-3-图像提示词的五条原则" tabindex="-1">24.3 图像提示词的五条原则 <a class="header-anchor" href="#_24-3-图像提示词的五条原则" aria-label="Permalink to &quot;24.3 图像提示词的五条原则&quot;">​</a></h2><p>这套原则是通用的，换任何模型都成立。</p><table tabindex="0"><thead><tr><th>#</th><th>原则</th><th>反例 ❌</th><th>正例 ✅</th></tr></thead><tbody><tr><td>1</td><td><strong>具体而非抽象</strong></td><td>&quot;科技感&quot;</td><td>&quot;深蓝色背景，半透明电路板纹理，冷光边缘&quot;</td></tr><tr><td>2</td><td><strong>风格前置</strong></td><td>把风格写在句尾</td><td><code>photorealistic</code> / <code>3D render</code> / <code>watercolor</code> 放开头</td></tr><tr><td>3</td><td><strong>构图指引</strong></td><td>不提视角</td><td>&quot;低角度仰拍、主体居中、浅景深&quot;</td></tr><tr><td>4</td><td><strong>光线描述</strong></td><td>&quot;灯光好一点&quot;</td><td>&quot;黄金时刻侧逆光、暖色温、柔和高光&quot;</td></tr><tr><td>5</td><td><strong>语言匹配</strong></td><td>对 DALL·E 用中文长句</td><td>DALL·E 用英文，Seedance 系列用中文</td></tr></tbody></table><h3 id="_24-3-1-两个可套用的模板" tabindex="-1">24.3.1 两个可套用的模板 <a class="header-anchor" href="#_24-3-1-两个可套用的模板" aria-label="Permalink to &quot;24.3.1 两个可套用的模板&quot;">​</a></h3><p><strong>写实摄影风格：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>A photorealistic [主体], [动作/姿态], [环境], [光线],</span></span>
<span class="line"><span>[构图], shot on [相机/镜头参考], [色调], 8K, highly detailed</span></span></code></pre></div><p><strong>数字艺术 / 插画风格：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[艺术风格], [主体], [场景描述], [配色],</span></span>
<span class="line"><span>[技法], inspired by [风格参考], [光线/情绪], detailed illustration</span></span></code></pre></div><blockquote><p>实用技巧：<strong>不确定怎么写，就先告诉我&quot;参考哪张图/哪个品牌/哪种感觉&quot;</strong>，我来翻译成上面这种结构化提示词。</p></blockquote><h2 id="_24-4-视频生成-为什么我坚持先给你脚本" tabindex="-1">24.4 视频生成：为什么我坚持先给你脚本 <a class="header-anchor" href="#_24-4-视频生成-为什么我坚持先给你脚本" aria-label="Permalink to &quot;24.4 视频生成：为什么我坚持先给你脚本&quot;">​</a></h2><p>视频技能有一个<strong>所有 7 个技能共享的强制机制</strong>，这是本章最重要的知识点：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你提需求</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>我分析需求，输出 2-3 个脚本版本（放在 video-script 代码块里）</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>我停止，等你确认 ← 关键：我不能自己往下走</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>你在界面上点「直接生成视频」</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>我才调用工具生成</span></span></code></pre></div><p><strong>为什么要有这道门禁？</strong></p><table tabindex="0"><thead><tr><th>原因</th><th>说明</th></tr></thead><tbody><tr><td>💰 成本</td><td>视频生成比图片贵得多，返工代价大</td></tr><tr><td>⏱️ 时间</td><td>一次生成几十秒起，多版本试错更慢</td></tr><tr><td>🎯 选择权</td><td>2-3 个版本是给你<strong>选</strong>的，不是给我凑数</td></tr><tr><td>🔍 可控</td><td>脚本是&quot;文字分镜&quot;，改脚本比改视频便宜 100 倍</td></tr></tbody></table><p><strong>所以你会看到我这样干活，这是正常的，不是卡住了：</strong></p><ul><li>✅ 输出脚本 → 停下来等你 → 确认后再生成</li><li>❌ 直接用你的原话当提示词（跳过优化）</li><li>❌ 只给 1 个版本（你没得选）</li><li>❌ 不等确认就自己开跑（剥夺你的选择权）</li></ul><blockquote><p>如果哪天我一上来就&quot;嗖&quot;地开始生成视频，那不是效率高，那是坏了规矩。</p></blockquote><h2 id="_24-5-视频脚本的六要素" tabindex="-1">24.5 视频脚本的六要素 <a class="header-anchor" href="#_24-5-视频脚本的六要素" aria-label="Permalink to &quot;24.5 视频脚本的六要素&quot;">​</a></h2><p>不管是豆包、可灵、海螺还是 Sora，一条合格的脚本必须包含 <strong>6 个要素</strong>，缺一不可：</p><table tabindex="0"><thead><tr><th>要素</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td>🎯 主体</td><td>画面里是谁/是什么</td><td>一位穿米色风衣的女性</td></tr><tr><td>🏃 动作</td><td>在做什么</td><td>推开旋转门走进咖啡馆</td></tr><tr><td>🏞️ 场景</td><td>环境与氛围</td><td>雨天午后，玻璃上的水珠</td></tr><tr><td>🎥 镜头</td><td>机位与运动</td><td>跟随镜头，手持轻微晃动</td></tr><tr><td>💡 光影</td><td>光源与色调</td><td>窗边自然光，暖调，逆光轮廓</td></tr><tr><td>✨ 画质</td><td>质感与风格</td><td>电影感，35mm 胶片颗粒，4K</td></tr></tbody></table><p><strong>注意第 4 项（镜头）和第 5 项（光影）</strong>——这两项是业余和专业的最大分界。写成&quot;灯光亮一点&quot;会被判定为不合格；必须写成&quot;侧逆光、暖色温、柔和高光&quot;。</p><h3 id="_24-5-1-七个视频技能怎么选" tabindex="-1">24.5.1 七个视频技能怎么选 <a class="header-anchor" href="#_24-5-1-七个视频技能怎么选" aria-label="Permalink to &quot;24.5.1 七个视频技能怎么选&quot;">​</a></h3><table tabindex="0"><thead><tr><th>技能</th><th>模型</th><th>语言</th><th>特点</th></tr></thead><tbody><tr><td><code>doubao-seedance-video-gen</code></td><td>豆包 Seedance 2.0</td><td>中文</td><td>综合能力强，2-3 版脚本可选</td></tr><tr><td><code>doubao-seedance-fast-video-gen</code></td><td>Seedance 2.0 Fast</td><td>中文</td><td>快速出片，适合试想法</td></tr><tr><td><code>doubao-seedance-mini-video-gen</code></td><td>Seedance 2.0 Mini</td><td>中文</td><td>轻量短视频</td></tr><tr><td><code>kling-video-gen</code></td><td>可灵 1.6</td><td>中文</td><td>中文语义与人物表现好</td></tr><tr><td><code>minimax-hailuo-video-gen</code></td><td>海螺 2.3</td><td>中文</td><td>画面质感与动态自然</td></tr><tr><td><code>runway-video-gen</code></td><td>Runway Gen-3/Gen-4</td><td><strong>英文</strong></td><td>电影级镜头控制、运动笔刷</td></tr><tr><td><code>sora-video-gen</code></td><td>Sora</td><td><strong>英文</strong></td><td>写实与物理一致性</td></tr></tbody></table><blockquote><p>选择口诀：<strong>中文场景首选豆包/可灵/海螺；要电影感和镜头调度选 Runway；要极致写实选 Sora。</strong> 拿不准就让三个中文模型各出一版脚本对比。</p></blockquote><h2 id="_24-6-三个真实工作流" tabindex="-1">24.6 三个真实工作流 <a class="header-anchor" href="#_24-6-三个真实工作流" aria-label="Permalink to &quot;24.6 三个真实工作流&quot;">​</a></h2><h3 id="_24-6-1-工作流-a-一张品牌海报" tabindex="-1">24.6.1 工作流 A：一张品牌海报 <a class="header-anchor" href="#_24-6-1-工作流-a-一张品牌海报" aria-label="Permalink to &quot;24.6.1 工作流 A：一张品牌海报&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 你说：产品是什么 + 主色调 + 要不要留文字区 + 用在哪（公众号/电商/线下）</span></span>
<span class="line"><span>② 我出：2-3 条结构化英文提示词，标注风格差异</span></span>
<span class="line"><span>③ 你选：挑一条，或说&quot;第 2 条但换成竖版&quot;</span></span>
<span class="line"><span>④ 我生成：DALL·E 3（1024x1792）或 FLUX（带文字）</span></span></code></pre></div><p><strong>关键点</strong>：把&quot;要放标题的位置&quot;提前说，我会在构图里留白。</p><h3 id="_24-6-2-工作流-b-一条产品短片的脚本" tabindex="-1">24.6.2 工作流 B：一条产品短片的脚本 <a class="header-anchor" href="#_24-6-2-工作流-b-一条产品短片的脚本" aria-label="Permalink to &quot;24.6.2 工作流 B：一条产品短片的脚本&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 你说：产品 + 平台（抖音/视频号）+ 时长 + 想传递的情绪</span></span>
<span class="line"><span>② 我出：2-3 个分镜脚本（每版都含六要素），并标注差异</span></span>
<span class="line"><span>③ 你选：定版本 → 我再按镜头逐个生成</span></span>
<span class="line"><span>④ 后期：把生成的片段按分镜顺序拼接</span></span></code></pre></div><h3 id="_24-6-3-工作流-c-批量出图-电商-内容团队" tabindex="-1">24.6.3 工作流 C：批量出图（电商/内容团队） <a class="header-anchor" href="#_24-6-3-工作流-c-批量出图-电商-内容团队" aria-label="Permalink to &quot;24.6.3 工作流 C：批量出图（电商/内容团队）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 定模板：先跑通 1 张，锁定提示词结构 + 尺寸 + 风格</span></span>
<span class="line"><span>② 变量化：把&quot;产品名/卖点/背景色&quot;抽成变量</span></span>
<span class="line"><span>③ 批量跑：按清单循环生成，统一命名归档</span></span>
<span class="line"><span>④ 抽检：按比例抽查，不合格的单独重跑</span></span></code></pre></div><blockquote><p>批量场景的核心不是&quot;生成得快&quot;，而是<strong>先把模板固化下来</strong>——这正好和第 17 章&quot;把流程蒸馏成 Skill&quot;是一个思路。</p></blockquote><h2 id="_24-7-四个常见坑" tabindex="-1">24.7 四个常见坑 <a class="header-anchor" href="#_24-7-四个常见坑" aria-label="Permalink to &quot;24.7 四个常见坑&quot;">​</a></h2><table tabindex="0"><thead><tr><th>坑</th><th>现象</th><th>解法</th></tr></thead><tbody><tr><td>用中文长句喂 DALL·E</td><td>画面偏题、细节丢失</td><td>换成英文结构化提示词</td></tr><tr><td>视频不等脚本直接生成</td><td>结果不可控、浪费额度</td><td>坚持走&quot;脚本 → 确认&quot;流程</td></tr><tr><td>只用一句话描述风格</td><td>每次结果差异巨大</td><td>把风格、构图、光线写全</td></tr><tr><td>竖版需求用方图生成再裁</td><td>构图被裁坏</td><td>直接指定竖版尺寸</td></tr></tbody></table><h2 id="_24-8-本章练习" tabindex="-1">24.8 本章练习 <a class="header-anchor" href="#_24-8-本章练习" aria-label="Permalink to &quot;24.8 本章练习&quot;">​</a></h2><ol><li><strong>做一次对照实验</strong>：同一个需求，分别用&quot;一句话&quot;和&quot;结构化提示词&quot;各生成一次，对比差异。</li><li><strong>写一份六要素脚本</strong>：随便挑一个你熟悉的产品，用 24.5 的六要素表格写一条 15 秒视频脚本。</li><li><strong>锁定一个模板</strong>：把你工作里最高频的出图需求，固化成一条可复用的提示词模板。</li></ol><hr><blockquote><p>小结：图像和视频生成，<strong>考的从来不是模型，是你能不能把&quot;想要的画面&quot;翻译成结构化的描述</strong>。四个图像模型各有特长，七个视频模型共享同一道确认门禁——理解这两点，你就已经超过 90% 的使用者了。</p></blockquote>`,58)])])}const b=d(n,[["render",s]]);export{u as __pageData,b as default};
